<?php foreach ($sections as $section): ?>
<?php $type = $section['section_type']; $hasImage = ! empty($section['image']); ?>
<?php if ($type === 'hero'): ?>
<section class="builder-hero"<?= $hasImage ? ' style="background-image:linear-gradient(rgba(5,21,36,.78),rgba(5,21,36,.78)),url(\'' . esc($section['image'], 'attr') . '\')"' : '' ?>><div class="container"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><div class="builder-copy"><?= $section['content'] ?></div><?php if ($section['button_label'] && $section['button_url']): ?><a class="button" href="<?= esc($section['button_url']) ?>"><?= esc($section['button_label']) ?></a><?php endif ?></div></section>
<?php elseif ($type === 'image_text'): ?>
<section class="container builder-split"><div class="builder-copy"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><?= $section['content'] ?><?php if ($section['button_label'] && $section['button_url']): ?><a class="button" href="<?= esc($section['button_url']) ?>"><?= esc($section['button_label']) ?></a><?php endif ?></div><?php if ($hasImage): ?><img src="<?= esc($section['image']) ?>" alt="<?= esc($section['image_alt']) ?>"><?php endif ?></section>
<?php elseif ($type === 'call_to_action'): ?>
<section class="builder-cta"><div class="container"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><div class="builder-copy"><?= $section['content'] ?></div><?php if ($section['button_label'] && $section['button_url']): ?><a class="button" href="<?= esc($section['button_url']) ?>"><?= esc($section['button_label']) ?></a><?php endif ?></div></section>
<?php elseif ($type === 'stat_grid'): ?>
<section class="container builder-stats"><div><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2></div><div class="stat-grid"><?php foreach ($section['item_rows'] as $item): ?><article><strong><?= esc($item['value']) ?></strong><span><?= esc($item['label']) ?></span></article><?php endforeach ?></div></section>
<?php elseif ($type === 'gallery'): ?>
<section class="container builder-gallery"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><?php if ($section['content']): ?><div class="builder-copy"><?= $section['content'] ?></div><?php endif ?><div><?php foreach ($section['item_rows'] as $item): ?><?php if (preg_match('#^/(?:uploads/|assets/media/)#i', $item['label'])): ?><button class="gallery-trigger" type="button" data-lightbox-src="<?= esc($item['label'], 'attr') ?>" data-lightbox-alt="<?= esc($item['value'], 'attr') ?>"><img src="<?= esc($item['label']) ?>" alt="<?= esc($item['value']) ?>"><span class="gallery-zoom" aria-hidden="true">View image</span></button><?php endif ?><?php endforeach ?></div></section>
<?php elseif ($type === 'trust_strip'): ?>
<section class="builder-trust"><div class="container"><div class="builder-trust-heading"><p class="eyebrow dark"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><?php if ($section['content']): ?><div class="builder-copy"><?= $section['content'] ?></div><?php endif ?></div><div class="trust-items"><?php foreach ($section['item_rows'] as $item): ?><article><strong><?= esc($item['label']) ?></strong><span><?= esc($item['value']) ?></span></article><?php endforeach ?></div></div></section>
<?php elseif ($type === 'testimonial_carousel'): ?>
<section class="builder-testimonials"><div class="container"><div class="testimonial-intro"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><?php if ($section['content']): ?><div class="builder-copy"><?= $section['content'] ?></div><?php endif ?></div><?php if ($section['item_rows']): ?><div class="testimonial-carousel" data-carousel aria-roledescription="carousel"><div class="testimonial-slides"><?php foreach ($section['item_rows'] as $index => $item): ?><figure class="testimonial-slide<?= $index === 0 ? ' is-active' : '' ?>" data-carousel-slide<?= $index === 0 ? '' : ' hidden' ?>><blockquote>“<?= esc($item['label']) ?>”</blockquote><figcaption><?= esc($item['value']) ?></figcaption></figure><?php endforeach ?></div><?php if (count($section['item_rows']) > 1): ?><div class="carousel-controls"><button type="button" data-carousel-prev aria-label="Show previous testimonial">←</button><span data-carousel-status aria-live="polite">1 of <?= count($section['item_rows']) ?></span><button type="button" data-carousel-next aria-label="Show next testimonial">→</button></div><?php endif ?></div><?php endif ?></div></section>
<?php elseif ($type === 'faq'): ?>
<section class="container builder-faq"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><?php foreach ($section['item_rows'] as $item): ?><details><summary><?= esc($item['label']) ?></summary><p><?= esc($item['value']) ?></p></details><?php endforeach ?></section>
<?php else: ?>
<section class="container builder-rich"><p class="eyebrow"><?= esc($section['eyebrow']) ?></p><h2><?= esc($section['heading']) ?></h2><div class="builder-copy prose"><?= $section['content'] ?></div></section>
<?php endif ?>
<?php endforeach ?>
